import React, { useEffect, useMemo, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { User, Lock, Clock, Mail, Calendar, Key, Zap, Settings, Shield, Edit, Trash2 } from 'lucide-react';
import styles from './UserManagerInfoPage.module.css';
import { useAuth } from '../../auth/context';
import { updateProfileApi } from '../../../shared/api';
import {
  clearPromptHistory,
  getApiErrorMessage,
  getPromptHistory,
  getStoredAuth,
  getUserSettings,
  patchUserSettings,
  setStoredAuth,
} from '../../../shared/services';
import { useToast } from '../../../shared/ui';

function buildUserData(currentUser, role) {
  const username = currentUser?.username || 'TechUser_789';
  const email = currentUser?.email || 'user@ainode.com';
  const registrationTimestamp = Number(currentUser?.registrationTimestamp);
  const joinDate = Number.isFinite(registrationTimestamp) && registrationTimestamp > 0
    ? new Date(registrationTimestamp).toLocaleDateString()
    : 'Khong co';

  return {
    username,
    email,
    joinDate,
    accessLevel: role === 'ROLE_ADMIN' ? 'Quan tri vien' : 'Nguoi dung Pro',
    lastLogin: new Date().toLocaleString(),
  };
}

function formatPromptDate(value) {
  const parsedDate = new Date(value);
  if (Number.isNaN(parsedDate.getTime())) {
    return 'Khong co';
  }
  return parsedDate.toLocaleString();
}

function mapPrivacyLabel(value) {
  if (value === 'Private') return 'Rieng tu';
  if (value === 'Semi-Private') return 'An danh';
  if (value === 'Public') return 'Cong khai';
  return 'Rieng tu';
}

function mapPromptStatusLabel(value) {
  if (value === 'Failed') return 'That bai';
  return 'Hoan tat';
}

const UserManagerInfoPage = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { currentUser, auth, fetchMe } = useAuth();
  const { showToast } = useToast();
  const currentUsername = currentUser?.username || 'guest';

  const [activeTab, setActiveTab] = useState('account');
  const [isEditing, setIsEditing] = useState(false);
  const [isSavingProfile, setIsSavingProfile] = useState(false);

  const initialUserData = useMemo(() => buildUserData(currentUser, auth?.role), [currentUser, auth?.role]);
  const [userData, setUserData] = useState(initialUserData);
  const [userSettings, setUserSettings] = useState(() => getUserSettings(currentUsername));
  const [promptHistory, setPromptHistory] = useState(() => getPromptHistory(currentUsername));

  useEffect(() => {
    setUserData((prev) => {
      const next = buildUserData(currentUser, auth?.role);
      return {
        ...next,
        email: currentUser?.email || prev.email || next.email,
      };
    });
  }, [currentUser, auth?.role]);

  useEffect(() => {
    setUserSettings(getUserSettings(currentUsername));
    setPromptHistory(getPromptHistory(currentUsername));
  }, [currentUsername]);

  useEffect(() => {
    const queryTab = new URLSearchParams(location.search).get('tab');
    if (queryTab === 'account' || queryTab === 'security' || queryTab === 'history') {
      setActiveTab(queryTab);
    }
  }, [location.search]);

  const handleSaveProfile = async (e) => {
    e.preventDefault();
    if (isSavingProfile) return;

    const nextUsername = String(userData.username || '').trim();
    const nextEmail = String(userData.email || '').trim();

    if (!nextUsername || !nextEmail) {
      showToast('Ten dang nhap va email khong duoc de trong.', { type: 'error' });
      return;
    }

    setIsSavingProfile(true);
    try {
      const response = await updateProfileApi({
        username: nextUsername,
        email: nextEmail,
      });

      const currentAuth = getStoredAuth();
      if (response?.accessToken && currentAuth?.refreshToken) {
        setStoredAuth({
          ...currentAuth,
          accessToken: response.accessToken,
          tokenType: response?.tokenType || currentAuth?.tokenType || 'Bearer',
        });
      }

      setUserData((prev) => ({
        ...prev,
        username: response?.username || nextUsername,
        email: response?.email || nextEmail,
        lastLogin: new Date().toLocaleString(),
      }));

      await fetchMe();
      setIsEditing(false);
      showToast('Thong tin ca nhan da duoc cap nhat va dong bo voi may chu.', { type: 'success' });
    } catch (error) {
      showToast(getApiErrorMessage(error, 'Khong cap nhat duoc thong tin ca nhan.'), { type: 'error' });
    } finally {
      setIsSavingProfile(false);
    }
  };

  const updateSettings = (patch, successMessage) => {
    const next = patchUserSettings(currentUsername, patch);
    setUserSettings(next);
    if (successMessage) {
      showToast(successMessage, { type: 'success' });
    }
  };

  const handlePrivacyChange = (e) => {
    const nextPrivacy = e.target.value;
    const autoShareData = nextPrivacy === 'Public';

    updateSettings(
      {
        privacySetting: nextPrivacy,
        shareDataForTraining: autoShareData ? true : userSettings.shareDataForTraining,
      },
      `Quyen rieng tu da duoc dat thanh: ${mapPrivacyLabel(nextPrivacy)}`,
    );
  };

  const handleFaceVerificationToggle = () => {
    const nextValue = !userSettings.faceVerificationEnabled;
    const next = patchUserSettings(currentUsername, { faceVerificationEnabled: nextValue });
    patchUserSettings('guest', { faceVerificationEnabled: nextValue });
    setUserSettings(next);
    showToast(nextValue ? 'Da bat xac nhan khuon mat.' : 'Da tat xac nhan khuon mat.', { type: 'success' });
  };

  const handleVoiceChatToggle = () => {
    const nextValue = !userSettings.voiceChatEnabled;
    const next = patchUserSettings(currentUsername, { voiceChatEnabled: nextValue });
    setUserSettings(next);
    showToast(nextValue ? 'Da bat tro chuyen giong noi va giong doc nu he thong.' : 'Da tat tro chuyen giong noi.', { type: 'success' });
  };

  const handleClearPromptHistory = () => {
    clearPromptHistory(currentUsername);
    setPromptHistory([]);
    showToast('Da xoa toan bo lich su cau lenh tren trinh duyet nay.', { type: 'info' });
  };

  const handleRefreshPromptHistory = () => {
    setPromptHistory(getPromptHistory(currentUsername));
  };

  const renderAccountInfo = () => (
    <div className={styles.formSection}>
      <h2 className={styles.sectionTitle}>
        <User size={18} style={{ marginRight: '8px' }} /> Thong tin co ban
      </h2>

      {!isEditing ? (
        <div className={styles.infoGrid}>
          <div className={styles.infoCard}>
            <p>
              <strong><User size={14} style={{ marginRight: '5px' }} /> Ten dang nhap:</strong> {userData.username}
            </p>
            <p>
              <strong><Mail size={14} style={{ marginRight: '5px' }} /> Email:</strong> {userData.email}
            </p>
            <p>
              <strong><Key size={14} style={{ marginRight: '5px' }} /> Cap truy cap:</strong> {userData.accessLevel}
            </p>
          </div>
          <div className={styles.infoCard}>
            <p>
              <strong><Calendar size={14} style={{ marginRight: '5px' }} /> Ngay tham gia:</strong> {userData.joinDate}
            </p>
            <p>
              <strong><Clock size={14} style={{ marginRight: '5px' }} /> Dang nhap cuoi:</strong> {userData.lastLogin}
            </p>
            <p>
              <strong><Lock size={14} style={{ marginRight: '5px' }} /> Xac thuc khuon mat:</strong> {userSettings.faceVerificationEnabled ? 'Da bat' : 'Da tat'}
            </p>
            <p>
              <strong><Clock size={14} style={{ marginRight: '5px' }} /> Tro chuyen giong noi:</strong> {userSettings.voiceChatEnabled ? 'Da bat' : 'Da tat'}
            </p>
          </div>
        </div>
      ) : (
        <form onSubmit={handleSaveProfile}>
          <div className={styles.inputGroup}>
            <label className={styles.inputLabel}>Ten dang nhap</label>
            <input
              type="text"
              className={styles.inputField}
              value={userData.username}
              onChange={(e) => setUserData({ ...userData, username: e.target.value })}
            />
          </div>
          <div className={styles.inputGroup}>
            <label className={styles.inputLabel}>Email</label>
            <input
              type="email"
              className={styles.inputField}
              value={userData.email}
              onChange={(e) => setUserData({ ...userData, email: e.target.value })}
            />
          </div>
          <button type="submit" className={styles.saveButton} disabled={isSavingProfile}>
            <Zap size={16} style={{ marginRight: '8px' }} /> {isSavingProfile ? 'Dang luu...' : 'Luu thay doi'}
          </button>
          <button type="button" className={styles.actionButton} style={{ backgroundColor: '#4b5563' }} onClick={() => setIsEditing(false)}>
            Huy
          </button>
        </form>
      )}

      <button className={styles.actionButton} style={{ marginTop: '20px' }} onClick={() => setIsEditing(!isEditing)}>
        <Edit size={16} style={{ marginRight: '8px' }} /> {isEditing ? 'Huy chinh sua' : 'Chinh sua thong tin'}
      </button>
    </div>
  );

  const renderSecurityPrivacy = () => (
    <>
      <div className={styles.formSection}>
        <h2 className={styles.sectionTitle}>
          <Shield size={18} style={{ marginRight: '8px' }} /> Bao mat tai khoan
        </h2>
        <p className="text-sm text-gray-400 mb-4">Client luu local va dong bo voi backend o cac endpoint ho tro.</p>

        <div className={styles.inputGroup}>
          <label className={styles.inputLabel}>Xac thuc hai yeu to (2FA)</label>
          <button
            type="button"
            className={styles.saveButton}
            style={{ backgroundColor: userSettings.twoFactorEnabled ? '#ef4444' : '#48bb78', width: '220px' }}
            onClick={() =>
              updateSettings(
                { twoFactorEnabled: !userSettings.twoFactorEnabled },
                userSettings.twoFactorEnabled ? 'Da tat 2FA tren client.' : 'Da bat 2FA tren client.',
              )}
          >
            {userSettings.twoFactorEnabled ? 'Tat 2FA' : 'Kich hoat 2FA'}
          </button>
        </div>

        <div className={styles.inputGroup}>
          <label className={styles.inputLabel}>Xac nhan khuon mat khi dang nhap</label>
          <button
            type="button"
            className={styles.saveButton}
            style={{ backgroundColor: userSettings.faceVerificationEnabled ? '#ef4444' : '#48bb78', width: '260px' }}
            onClick={handleFaceVerificationToggle}
          >
            {userSettings.faceVerificationEnabled ? 'Tat xac nhan khuon mat' : 'Bat xac nhan khuon mat'}
          </button>
        </div>

        <div className={styles.inputGroup}>
          <label className={styles.inputLabel}>Tro chuyen giong noi (mic + doc cau tra loi)</label>
          <button
            type="button"
            className={styles.saveButton}
            style={{ backgroundColor: userSettings.voiceChatEnabled ? '#ef4444' : '#48bb78', width: '280px' }}
            onClick={handleVoiceChatToggle}
          >
            {userSettings.voiceChatEnabled ? 'Tat tro chuyen giong noi' : 'Bat tro chuyen giong noi'}
          </button>
        </div>
      </div>

      <div className={styles.formSection}>
        <h2 className={styles.sectionTitle}>
          <Lock size={18} style={{ marginRight: '8px' }} /> Quyen rieng tu du lieu
        </h2>
        <div className={styles.inputGroup}>
          <label className={styles.inputLabel}>Thiet lap quyen rieng tu tuong tac</label>
          <select className={styles.selectField} value={userSettings.privacySetting} onChange={handlePrivacyChange}>
            <option value="Private">Rieng tu (Khong dung de dao tao)</option>
            <option value="Semi-Private">An danh (An thong tin nhan dang)</option>
            <option value="Public">Cong khai (Dong gop de cai tien AI)</option>
          </select>
        </div>

        <div className={styles.inputGroup}>
          <label className={styles.inputLabel}>Chia se du lieu de AI thong minh hon</label>
          <button
            type="button"
            className={styles.saveButton}
            style={{ backgroundColor: userSettings.shareDataForTraining ? '#ef4444' : '#48bb78', width: '320px' }}
            onClick={() =>
              updateSettings(
                { shareDataForTraining: !userSettings.shareDataForTraining },
                userSettings.shareDataForTraining
                  ? 'Da tat chia se du lieu huan luyen AI.'
                  : 'Da bat chia se du lieu huan luyen AI.',
              )}
          >
            {userSettings.shareDataForTraining ? 'Tat chia se du lieu huan luyen' : 'Bat chia se du lieu huan luyen'}
          </button>
        </div>

        <button type="button" className={`${styles.actionButton} ${styles.dangerButton}`} onClick={handleClearPromptHistory}>
          <Trash2 size={16} style={{ marginRight: '8px' }} /> Xoa toan bo lich su cau lenh
        </button>
      </div>
    </>
  );

  const renderPromptHistory = () => (
    <div className={styles.formSection}>
      <h2 className={styles.sectionTitle}>
        <Clock size={18} style={{ marginRight: '8px' }} /> Lich su cau lenh chat
      </h2>
      <p className="text-sm text-gray-400 mb-4">Du lieu duoc luu local theo tung tai khoan dang nhap tren client.</p>

      <div style={{ marginBottom: '10px' }}>
        <button type="button" className={styles.actionButton} onClick={handleRefreshPromptHistory}>
          Lam moi lich su
        </button>
      </div>

      <table className={styles.promptTable}>
        <thead>
          <tr>
            <th>ID</th>
            <th>Loai cau lenh</th>
            <th>Noi dung tom tat</th>
            <th>Ngay</th>
            <th>Trang thai</th>
            <th>Token su dung</th>
          </tr>
        </thead>
        <tbody>
          {promptHistory.length === 0 && (
            <tr>
              <td colSpan={6}>Chua co cau lenh nao duoc luu.</td>
            </tr>
          )}
          {promptHistory.map((prompt, index) => (
            <tr key={prompt.id}>
              <td>{index + 1}</td>
              <td>
                <span className={`${styles.statusTag} ${prompt.type === 'text' ? styles.text : styles.voice}`}>
                  {prompt.type === 'text' ? 'VAN BAN' : 'GIONG NOI'}
                </span>
              </td>
              <td>{prompt.content.length > 70 ? `${prompt.content.substring(0, 70)}...` : prompt.content}</td>
              <td>{formatPromptDate(prompt.createdAt)}</td>
              <td>{mapPromptStatusLabel(prompt.status)}</td>
              <td>{prompt.tokens}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );

  return (
    <div className={styles.container}>
      <div className={styles.contentBox}>
        <div className={styles.topActions}>
          <button type="button" className={styles.backButton} onClick={() => navigate('/home')}>
            Quay ve trang chu
          </button>
        </div>

        <h1 className={styles.title}>
          <Settings size={30} style={{ marginRight: '10px' }} /> Cai dat & Quan ly tai khoan AI Node
        </h1>

        <div className={styles.tabsContainer}>
          <button className={`${styles.tabButton} ${activeTab === 'account' ? styles.tabButtonActive : ''}`} onClick={() => setActiveTab('account')}>
            <User size={16} style={{ marginRight: '8px' }} /> Thong tin ca nhan
          </button>
          <button className={`${styles.tabButton} ${activeTab === 'security' ? styles.tabButtonActive : ''}`} onClick={() => setActiveTab('security')}>
            <Shield size={16} style={{ marginRight: '8px' }} /> Bao mat & Quyen rieng tu
          </button>
          <button className={`${styles.tabButton} ${activeTab === 'history' ? styles.tabButtonActive : ''}`} onClick={() => setActiveTab('history')}>
            <Clock size={16} style={{ marginRight: '8px' }} /> Lich su cau lenh
          </button>
        </div>

        {activeTab === 'account' && renderAccountInfo()}
        {activeTab === 'security' && renderSecurityPrivacy()}
        {activeTab === 'history' && renderPromptHistory()}
      </div>
    </div>
  );
};

export default UserManagerInfoPage;
